Rewrite the following MS C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to rewrite:
<original_code>
#define use_crt_defines
#define _ert_No_deprecate

#include <iostream>
#include <cstdio>
#include <cstring>
#include <string>
#include <algorithm>
#include <cmath>
using namespace std;
long long n, x, y;
long long gcd(long long a, long long b)
{
	while(b)
	{
		a %= b;
		swap(a,b);
	}
	return a;
}
struct dro
{
	long long ch;
	long long zn;
	dro()
	{}
	dro(long long a, long long b)
	{
		ch = a;
		zn = b;
	}
	void operator - (const dro &a)
	{
		ch = ch * a.zn - a.ch * zn;
		zn = zn * a.zn;
	}
	bool operator < (const dro &a) const
	{
		if (ch * a.zn < a.ch * zn)
			return true;
		else
			return false;
	}
	void cok()
	{
		long long j = gcd(ch, zn);
		ch /= j;
		zn /= j;
	}
	void sho()
	{
		cout << ch << "/" << zn;
	}
};

int main ()
{
	//freopen("input.txt", "r", stdin);
	cin >> x >> y >> n;
	dro os(50, 1);
	dro na(x, y), ot;
	for (long long i = 1; i <= n; ++i)
	{
		dro p;
		long long r = (na.ch * i) / na.zn;
		long long z = (na.ch * i) % na.zn;
		if (z > (na.zn / 2))
			r++, z = na.zn - z;
		p.ch = z;
		p.zn = i * na.zn;
		if (p < os)
		{	
			os = p;
			ot.ch = r;
			ot.zn = i;
		}
	}
	ot.sho();
}
</original_code>
